<script setup lang="ts">
import { reactive, ref } from 'vue'
import { showToast } from 'vant'
import { visitorApi } from '../../api'
import { errorMessage } from '../../api/client'
import ProductCard from '../../components/ProductCard.vue'
import type { Recommendation } from '../../types'
const loading = ref(false); const results = ref<Recommendation[]>([]); const form = reactive({ target_date: '', weather: 'RAIN', adult_count: 2, child_count: 1, child_ages: '6', budget: '700', interests: '手工', dietary_restrictions: '', allergy_information: '', arrival_time: '15:00', preferred_experience_time: '16:00', other_requirements: '' })
async function submit() { loading.value = true; try { const response = await visitorApi.recommend({ target_date: form.target_date || undefined, weather: form.weather, adult_count: form.adult_count, child_count: form.child_count, child_ages: form.child_count ? form.child_ages.split(/[,，]/).filter(Boolean).map(Number) : [], budget: form.budget, interests: form.interests.split(/[,，]/).filter(Boolean), dietary_restrictions: form.dietary_restrictions.split(/[,，]/).filter(Boolean), allergy_information: form.allergy_information, arrival_time: form.arrival_time || undefined, preferred_experience_time: form.preferred_experience_time || undefined, other_requirements: form.other_requirements }); results.value = response.data.results; if (!results.value.length) showToast('当前没有完全匹配的可售套餐'); else showToast(`已找到 ${results.value.length} 个推荐`) } catch (e) { showToast(errorMessage(e)) } finally { loading.value = false } }
</script>
<template><div class="page-head"><div><div class="eyebrow">PERSONAL MATCHING</div><h1>说说你的杭州周末</h1><p>把人数、预算、兴趣和过敏信息告诉我们，系统会先做确定性筛选，再生成易懂的推荐解释。</p></div></div><div class="split-layout"><div class="panel sticky-panel"><div class="section-title" style="margin-top:0"><h2>你的需求</h2><span>无需注册</span></div><el-form label-position="top"><div class="form-grid"><el-form-item class="full" label="入住日期"><el-date-picker v-model="form.target_date" type="date" value-format="YYYY-MM-DD" style="width:100%" placeholder="不指定" /></el-form-item><el-form-item label="成人"><el-input-number v-model="form.adult_count" :min="1" style="width:100%" /></el-form-item><el-form-item label="儿童"><el-input-number v-model="form.child_count" :min="0" style="width:100%" /></el-form-item><el-form-item class="full" label="儿童年龄"><el-input v-model="form.child_ages" placeholder="例如 6,9" /></el-form-item><el-form-item label="预算上限"><el-input v-model="form.budget"><template #prepend>¥</template></el-input></el-form-item><el-form-item label="天气"><el-select v-model="form.weather" style="width:100%"><el-option label="小雨" value="RAIN" /><el-option label="晴天" value="SUNNY" /><el-option label="多云" value="CLOUDY" /></el-select></el-form-item><el-form-item class="full" label="兴趣偏好"><el-input v-model="form.interests" placeholder="手工, 茶文化" /></el-form-item><el-form-item class="full" label="饮食禁忌"><el-input v-model="form.dietary_restrictions" placeholder="例如：不吃辣" /></el-form-item><el-form-item class="full" label="过敏信息"><el-input v-model="form.allergy_information" type="textarea" :rows="2" placeholder="例如：花生过敏" /></el-form-item><el-form-item label="预计到店"><el-time-select v-model="form.arrival_time" start="08:00" step="00:30" end="22:00" style="width:100%" /></el-form-item><el-form-item label="期望体验时间"><el-time-select v-model="form.preferred_experience_time" start="08:00" step="00:30" end="22:00" style="width:100%" /></el-form-item></div><el-button type="primary" size="large" :loading="loading" style="width:100%" @click="submit">获取个性化推荐</el-button></el-form></div><div><div v-if="!results.length && !loading" class="panel empty-state"><div><div style="font-size:36px;color:#b8d8ce">♡</div><p>提交你的需求后，推荐结果会显示在这里。</p></div></div><div v-if="loading" class="panel empty-state">正在匹配库存、天气、年龄与时间约束…</div><div v-for="item in results" :key="item.product.id" class="panel" style="margin-bottom:14px"><div class="product-card__top"><span class="eyebrow">匹配分 {{ item.score }}</span><span class="muted">{{ item.product.sale_quantity }} 套可售</span></div><ProductCard :product="item.product" public-view /><p style="line-height:1.7;font-size:13px">{{ item.recommendation_reason }}</p><div class="product-card__resources"><span :class="item.budget_match ? '' : 'warning-text'">预算 {{ item.budget_match ? '匹配' : '超出' }}</span><span>儿童 {{ item.children_match ? '适配' : '需确认' }}</span><span>天气 {{ item.weather_match ? '适配' : '不适配' }}</span></div><div v-if="item.schedule.length" class="panel" style="box-shadow:none;background:#f8fbf9;margin-top:12px"><strong>时间安排</strong><p v-for="event in item.schedule" :key="event.time + event.title" class="muted" style="line-height:1.5;margin:8px 0"><b>{{ event.time }}</b> · {{ event.title }}：{{ event.description }}</p></div><div v-if="item.allergy_warning" class="danger-text" style="font-size:12px;line-height:1.7;margin-top:12px">{{ item.allergy_warning }}</div><div style="text-align:right;margin-top:12px"><el-button type="primary" plain @click="$router.push(`/visitor/products/${item.product.id}`)">查看套餐并预约</el-button></div></div></div></div></template>

